v093-admin-script:
/* ===== V4.02 Supabase Admin Panel ===== */
let v093IsAdmin=false;
let v093Events=[];
let v093News=[];

function v093Esc(v){return v073Escape(String(v??''))}

async function v093CheckAdmin(){
  if(!(await v073Init()) || !v073User)return false;

  const {data,error}=await v073Db
    .from('game_admins')
    .select('user_id')
    .eq('user_id',v073User.id)
    .maybeSingle();

  v093IsAdmin=!error && !!data;

  const state=document.querySelector('#v093AdminState');
  const content=document.querySelector('#v093AdminContent');
  const denied=document.querySelector('#v093AdminDenied');

  if(state){
    state.textContent=v093IsAdmin?'ADMIN':'KEIN ZUGRIFF';
    state.style.color=v093IsAdmin?'#a9e893':'#ef9d98';
  }
  if(content)content.style.display=v093IsAdmin?'block':'none';
  if(denied)denied.style.display=v093IsAdmin?'none':'block';

  v093BuildMenu();
  return v093IsAdmin;
}

async function v093LoadPublicContent(){
  if(!(await v073Init()))return;
  if(!v073User?.id)return;

  try{
    const now=new Date().toISOString();

    const ev=await v073Db
      .from('game_events')
      .select('id,name,description,starts_at,ends_at,is_active,created_at')
      .order('created_at',{ascending:false});

    if(!ev.error)v093Events=ev.data||[];

    const nw=await v073Db
      .from('game_news')
      .select('id,version,title,body,is_published,created_at')
      .eq('is_published',true)
      .order('created_at',{ascending:false})
      .limit(8);

    if(!nw.error)v093News=nw.data||[];

    if(document.querySelector('#world')?.classList.contains('active')){
      v085InstallWorld();
    }
  }catch(e){
    console.error('V4.02 public content',e);
  }
}

v085ActiveEvents=function(){
  const now=Date.now();
  const active=(v093Events||[]).filter(ev=>{
    if(!ev.is_active)return false;
    const start=ev.starts_at?new Date(ev.starts_at).getTime():0;
    const end=ev.ends_at?new Date(ev.ends_at).getTime():Infinity;
    return now>=start && now<=end;
  });

  if(!active.length){
    return `
      <div class="v085-event-card">
        <div class="v085-event-title">Aktuell kein Event aktiv</div>
        <div class="v085-event-sub">Sobald ein Event startet, erscheint es hier direkt.</div>
        <div class="v085-event-status">KEIN EVENT</div>
      </div>`;
  }

  return active.map(ev=>`
    <div class="v085-event-card">
      <div class="v085-event-title">${v093Esc(ev.name)}</div>
      <div class="v085-event-sub">${v093Esc(ev.description||'Zeitlich begrenztes Event.')}</div>
      <div class="v085-event-status">AKTIV</div>
    </div>`).join('');
};

v085NewsHtml=function(){
  const source=(v093News||[]).length?v093News:[
    {version:'V4.02',title:'Dampf-System korrigiert',body:'Keine ungewollte Zeit-Regeneration mehr.'},
    {version:'V4.02',title:'Händler-Vergleich',body:'Shop-Items zeigen besser, schlechter oder gleichwertig.'},
    {version:'V4.02',title:'Neue Welt-Startseite',body:'Begrüßung, Events, Update-News und Schnellzugriffe.'}
  ];

  return source.map(n=>`
    <div class="v085-news">
      <div class="v085-news-top">
        <div class="v085-news-title">${v093Esc(n.title)}</div>
        <div class="v085-news-version">${v093Esc(n.version||'NEWS')}</div>
      </div>
      <div class="v085-news-text">${v093Esc(n.body||n.text||'')}</div>
    </div>`).join('');
};

async function v093AdminLoadLists(){
  if(!v093IsAdmin)return;

  const ev=await v073Db.from('game_events')
    .select('*').order('created_at',{ascending:false});

  if(!ev.error)v093Events=ev.data||[];

  const nw=await v073Db.from('game_news')
    .select('*').order('created_at',{ascending:false}).limit(20);

  const eventList=document.querySelector('#v093EventList');
  if(eventList){
    eventList.innerHTML=(v093Events||[]).map(ev=>`
      <div class="v093-admin-item">
        <div class="v093-admin-item-top">
          <b>${v093Esc(ev.name)}</b>
          <span class="pill">${ev.is_active?'AKTIV':'AUS'}</span>
        </div>
        <div class="tiny">${v093Esc(ev.description||'')}</div>
        <div class="v093-admin-actions">
          <button class="btn secondary" onclick="v093ToggleEvent('${ev.id}',${!ev.is_active})">${ev.is_active?'Deaktivieren':'Aktivieren'}</button>
          <button class="btn danger" onclick="v093DeleteEvent('${ev.id}')">Löschen</button>
        </div>
      </div>`).join('') || '<div class="empty">Noch keine Events.</div>';
  }

  const newsList=document.querySelector('#v093NewsList');
  if(newsList && !nw.error){
    newsList.innerHTML=(nw.data||[]).map(n=>`
      <div class="v093-admin-item">
        <div class="v093-admin-item-top">
          <b>${v093Esc(n.title)}</b>
          <span class="pill">${v093Esc(n.version||'NEWS')}</span>
        </div>
        <div class="tiny">${v093Esc(n.body||'')}</div>
        <div class="v093-admin-actions">
          <button class="btn secondary" onclick="v093ToggleNews('${n.id}',${!n.is_published})">${n.is_published?'Ausblenden':'Veröffentlichen'}</button>
          <button class="btn danger" onclick="v093DeleteNews('${n.id}')">Löschen</button>
        </div>
      </div>`).join('') || '<div class="empty">Noch keine News.</div>';
  }
}

async function v093SaveEvent(){
  if(!v093IsAdmin)return;

  const name=document.querySelector('#v093EventName')?.value.trim();
  const description=document.querySelector('#v093EventDesc')?.value.trim();
  const start=document.querySelector('#v093EventStart')?.value;
  const end=document.querySelector('#v093EventEnd')?.value;
  const active=!!document.querySelector('#v093EventActive')?.checked;

  if(!name)return v063Toast('Event-Name fehlt','warn');

  const {error}=await v073Db.from('game_events').insert({
    name,
    description,
    starts_at:start?new Date(start).toISOString():new Date().toISOString(),
    ends_at:end?new Date(end).toISOString():new Date(Date.now()+7*86400000).toISOString(),
    is_active:active,
    created_by:v073User.id
  });

  if(error)return v063Toast('Event konnte nicht gespeichert werden','error',error.message);

  v063Toast('Event gespeichert','success',name);
  await v093AdminLoadLists();
  await v093LoadPublicContent();
}

async function v093SaveNews(){
  if(!v093IsAdmin)return;

  const version=document.querySelector('#v093NewsVersion')?.value.trim()||'NEWS';
  const title=document.querySelector('#v093NewsTitle')?.value.trim();
  const body=document.querySelector('#v093NewsText')?.value.trim();

  if(!title||!body)return v063Toast('Titel und Text fehlen','warn');

  const {error}=await v073Db.from('game_news').insert({
    version,title,body,is_published:true,created_by:v073User.id
  });

  if(error)return v063Toast('News konnte nicht gespeichert werden','error',error.message);

  v063Toast('Update veröffentlicht · Login-Popup aktiv','success',title);
  await v093AdminLoadLists();
  await v093LoadPublicContent();
}

window.v093ToggleEvent=async(id,state)=>{
  if(!v093IsAdmin)return;
  await v073Db.from('game_events').update({is_active:state}).eq('id',id);
  await v093AdminLoadLists();
  await v093LoadPublicContent();
};

window.v093DeleteEvent=async(id)=>{
  if(!v093IsAdmin||!confirm('Event wirklich löschen?'))return;
  await v073Db.from('game_events').delete().eq('id',id);
  await v093AdminLoadLists();
  await v093LoadPublicContent();
};

window.v093ToggleNews=async(id,state)=>{
  if(!v093IsAdmin)return;
  await v073Db.from('game_news').update({is_published:state}).eq('id',id);
  await v093AdminLoadLists();
  await v093LoadPublicContent();
};

window.v093DeleteNews=async(id)=>{
  if(!v093IsAdmin||!confirm('News wirklich löschen?'))return;
  await v073Db.from('game_news').delete().eq('id',id);
  await v093AdminLoadLists();
  await v093LoadPublicContent();
};

function v093BuildMenu(){
  const panel=document.querySelector('#v032MenuPanel');
  if(!panel)return;

  const adminExisting=panel.querySelector('[data-screen="admin"]');

  if(v093IsAdmin && !adminExisting){
    const sep=document.createElement('div');
    sep.className='v086-menu-separator';
    const btn=document.createElement('button');
    btn.className='top-menu-item';
    btn.dataset.screen='admin';
    btn.innerHTML='<span>🛡️</span>Admin';
    btn.onclick=async()=>{
      v032Go('admin');
      await v093CheckAdmin();
      await v093AdminLoadLists();
    };
    panel.append(sep,btn);
  }

  if(!v093IsAdmin && adminExisting){
    adminExisting.previousElementSibling?.classList.contains('v086-menu-separator') && adminExisting.previousElementSibling.remove();
    adminExisting.remove();
  }
}

document.querySelector('#v093SaveEvent')?.addEventListener('click',v093SaveEvent);
document.querySelector('#v093SaveNews')?.addEventListener('click',v093SaveNews);

const v093BaseRender=render;
render=function(){
  v093BaseRender();

  v093BuildMenu();
};

(async()=>{
  try{
    await v093LoadPublicContent();
    await v093CheckAdmin();
    if(v093IsAdmin)await v093AdminLoadLists();
  }catch(e){console.error('V4.02 admin init',e)}
})();

v103-admin-player-editor-script:
/* ===== V4.02 Admin player value editor ===== */
let v103SelectedPlayer=null;

function v103InstallPlayerAdmin(){
  const adminContent=document.querySelector('#v093AdminContent');
  if(!adminContent || document.querySelector('#v103PlayerAdmin'))return;

  const card=document.createElement('div');
  card.className='card';
  card.id='v103PlayerAdmin';
  card.style.margin='12px 0 0';
  card.innerHTML=`
    <div class="section-title">
      <div>
        <h3>👥 Spieler verwalten</h3>
        <div class="muted">Cloud-Spielstand eines Spielers bearbeiten.</div>
      </div>
    </div>

    <div class="v103-player-search">
      <input id="v103PlayerSearch" class="v093-input" placeholder="Charaktername suchen">
      <button class="btn" id="v103PlayerSearchBtn">Suchen</button>
    </div>

    <div id="v103PlayerResults" class="v103-player-results"></div>

    <div id="v103PlayerEditor" class="v103-editor">
      <div class="v103-player-head">
        <b id="v103PlayerName">Spieler</b>
        <div id="v103PlayerMeta"></div>
      </div>

      <div class="v103-editor-grid">
        <div>
          <label class="v093-label">Level</label>
          <input id="v103Level" class="v093-input" type="number" min="1" max="999">
        </div>
        <div>
          <label class="v093-label">EXP</label>
          <input id="v103Xp" class="v093-input" type="number" min="0">
        </div>
        <div>
          <label class="v093-label">Gold</label>
          <input id="v103Gold" class="v093-input" type="number" min="0">
        </div>
        <div>
          <label class="v093-label">Harz-Taler</label>
          <input id="v103Harz" class="v093-input" type="number" min="0">
        </div>
        <div>
          <label class="v093-label">Dampf</label>
          <input id="v103Energy" class="v093-input" type="number" min="0" max="300">
        </div>
        <div>
          <label class="v093-label">Attributpunkte</label>
          <input id="v103Points" class="v093-input" type="number" min="0">
        </div>
        <div>
          <label class="v093-label">Talentpunkte</label>
          <input id="v103SkillPoints" class="v093-input" type="number" min="0">
        </div>
      </div>

      <button class="btn gold" id="v103SavePlayer" style="width:100%;margin-top:10px">
        Spielerwerte speichern
      </button>

      <div class="v103-warning">
        Änderungen werden im Cloud-Spielstand gespeichert. Ist der Spieler gerade online,
        sollte er danach das Spiel neu laden, damit sein lokaler Stand die Admin-Änderung
        nicht wieder überschreibt.
      </div>
    </div>`;

  adminContent.appendChild(card);

  document.querySelector('#v103PlayerSearchBtn').onclick=v103SearchPlayers;
  document.querySelector('#v103PlayerSearch').addEventListener('keydown',e=>{
    if(e.key==='Enter')v103SearchPlayers();
  });
  document.querySelector('#v103SavePlayer').onclick=v103SavePlayer;
}

async function v103SearchPlayers(){
  if(!v093IsAdmin)return;

  const q=document.querySelector('#v103PlayerSearch')?.value.trim()||'';
  const box=document.querySelector('#v103PlayerResults');
  if(!box)return;

  box.innerHTML='<div class="v072-empty">Spieler werden gesucht...</div>';

  const {data,error}=await v073Db.rpc('admin_search_players',{search_text:q});

  if(error){
    console.error(error);
    box.innerHTML='<div class="v072-status-offline">Spielersuche fehlgeschlagen. Admin-SQL ausführen.</div>';
    return;
  }

  const rows=Array.isArray(data)?data:[];
  box.innerHTML=rows.length?rows.map((p,i)=>`
    <button class="v103-player-result" data-v103-player="${v093Esc(p.user_id)}">
      <b>${v093Esc(p.character_name||'Unbenannt')}</b>
      <span>${v093Esc(p.class_name||'')} · Level ${Number(p.level)||1} · ${v093Esc(p.user_id).slice(0,8)}</span>
    </button>
  `).join(''):'<div class="v072-empty">Kein Spieler gefunden.</div>';

  box.querySelectorAll('[data-v103-player]').forEach(btn=>{
    btn.onclick=()=>v103LoadPlayer(btn.dataset.v103Player,btn);
  });
}

async function v103LoadPlayer(userId,button=null){
  if(!v093IsAdmin)return;

  const {data,error}=await v073Db.rpc('admin_get_player_values',{target_user:userId});

  if(error){
    console.error(error);
    return v063Toast('Spieler konnte nicht geladen werden','error',error.message);
  }

  const p=Array.isArray(data)?data[0]:data;
  if(!p)return v063Toast('Kein Cloud-Spielstand gefunden','warn');

  v103SelectedPlayer=p;

  document.querySelectorAll('.v103-player-result').forEach(x=>x.classList.remove('active'));
  button?.classList.add('active');

  document.querySelector('#v103PlayerName').textContent=p.character_name||'Spieler';
  document.querySelector('#v103PlayerMeta').textContent=`${p.class_name||''} · Spieler-ID ${String(p.user_id).slice(0,8)}`;

  document.querySelector('#v103Level').value=Number(p.level)||1;
  document.querySelector('#v103Xp').value=Number(p.xp)||0;
  document.querySelector('#v103Gold').value=Number(p.gold)||0;
  document.querySelector('#v103Harz').value=Number(p.harz_taler)||0;
  document.querySelector('#v103Energy').value=Number(p.energy)||0;
  document.querySelector('#v103Points').value=Number(p.points)||0;
  document.querySelector('#v103SkillPoints').value=Number(p.skill_points)||0;

  document.querySelector('#v103PlayerEditor').classList.add('show');
}

function v103Number(id,min=0,max=2147483647){
  let n=Math.floor(Number(document.querySelector(id)?.value)||0);
  return Math.max(min,Math.min(max,n));
}

async function v103SavePlayer(){
  if(!v093IsAdmin || !v103SelectedPlayer)return;

  const payload={
    target_user:v103SelectedPlayer.user_id,
    new_level:v103Number('#v103Level',1,999),
    new_xp:v103Number('#v103Xp',0,2000000000),
    new_gold:v103Number('#v103Gold',0,2000000000),
    new_harz_taler:v103Number('#v103Harz',0,2000000000),
    new_energy:v103Number('#v103Energy',0,300),
    new_points:v103Number('#v103Points',0,2000000000),
    new_skill_points:v103Number('#v103SkillPoints',0,2000000000)
  };

  if(!confirm(
    `Spielerwerte für ${v103SelectedPlayer.character_name} wirklich ändern?\n\n`+
    `Level ${payload.new_level}\nGold ${payload.new_gold}\nHarz-Taler ${payload.new_harz_taler}`
  ))return;

  const {data,error}=await v073Db.rpc('admin_update_player_values',payload);

  if(error){
    console.error(error);
    return v063Toast('Änderung fehlgeschlagen','error',error.message);
  }

  v063Toast('Spielerwerte gespeichert','success',`${v103SelectedPlayer.character_name} wurde aktualisiert.`);

  await v103LoadPlayer(v103SelectedPlayer.user_id);
  try{await v073LoadRanking()}catch(e){}
}

const v103OldAdminLoad=v093AdminLoadLists;
v093AdminLoadLists=async function(){
  const result=await v103OldAdminLoad();
  v103InstallPlayerAdmin();
  return result;
};

const v103BaseRender=render;
render=function(){
  v103BaseRender();

  if(v093IsAdmin)v103InstallPlayerAdmin();
};

try{
  if(v093IsAdmin)v103InstallPlayerAdmin();
}catch(e){console.error('V4.02 player admin',e)}

v274-events-gold-mystic-presets:
/* ===== V4.02 Event pack =====
   - Gold-Event: 2x quest Gold at claim time.
   - Mystisch-Event: 10% chance per completed quest for one genuine cyan class item.
   - Admin presets: Dampf, Erfahrung, Gold, Mystisch.
*/

function v274EventActive(words){
  const now=Date.now();
  const wanted=(Array.isArray(words)?words:[words]).map(x=>String(x).toLowerCase());
  return (v093Events||[]).some(ev=>{
    if(!ev?.is_active)return false;
    const name=String(ev.name||'').toLowerCase();
    if(!wanted.some(w=>name.includes(w)))return false;
    const start=ev.starts_at?new Date(ev.starts_at).getTime():0;
    const end=ev.ends_at?new Date(ev.ends_at).getTime():Infinity;
    return now>=start && now<=end;
  });
}
function v274GoldEventActive(){return v274EventActive(['gold'])}
function v274MysticEventActive(){return v274EventActive(['mystisch','mystic'])}

/* Final quest reward wrapper:
   Set quest Gold BEFORE the existing reward chain so all established
   reward modals/snapshots display the exact doubled amount. */
const v274BaseClaimQuest=claimQuest;
claimQuest=function(...args){
  const q=s.quests?.active;
  const ready=!!q && Date.now()>=Number(q.ends||0);

  if(ready){
    const baseGold=Math.max(0,Number(q.v274BaseGold ?? q.gold)||0);
    q.v274BaseGold=baseGold;
    q.gold=v274GoldEventActive()?baseGold*2:baseGold;
  }

  const beforeInv=Array.isArray(s.inventory)?s.inventory.length:0;
  const result=v274BaseClaimQuest.apply(this,args);

  /* A vanished active quest proves the established reward chain succeeded. */
  if(ready && !s.quests?.active){
    if(v274GoldEventActive()){
      try{
        v063Toast?.('💰 2× Gold Event!','success',`Diese Quest brachte ${Math.max(0,Number(q.gold)||0)} Gold.`);
      }catch(e){}
    }

    /* V4.56 loot contract:
       Mythic/cyan equipment is exclusive to an actual Smaragd-Koloss victory.
       A mystic event may activate the boss, but completed quests never mint cyan gear. */
  }

  return result;
};

/* Quest Cleanup Phase 2: the old V274 render-only Gold preview is retired.
   V276 is the later canonical Gold-event painter and writes the same doubled
   preview plus the visible ×2 badge. V274 claim/reward/event logic remains active. */

function v274LocalInput(d){
  return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);
}
function v274FillEventPreset(kind){
  const presets={
    dampf:{
      name:'Dampf-Event',
      desc:'Alle Spieler erhalten während des Events 300/300 Dampf.'
    },
    xp:{
      name:'Erfahrungs-Event',
      desc:'Quests geben während des Events 2× Erfahrung.'
    },
    gold:{
      name:'Gold-Event',
      desc:'Quests, Dungeons und Pflanzen-Ernten geben während des Events 2× Gold.'
    },
    mystic:{
      name:'Mystisch-Event',
      desc:'Abgeschlossene Quests können während des Events mystische Ausrüstung finden.'
    }
  };
  const x=presets[kind];if(!x)return;

  const now=new Date(),later=new Date(Date.now()+24*3600000);
  const name=document.querySelector('#v093EventName');
  const desc=document.querySelector('#v093EventDesc');
  const start=document.querySelector('#v093EventStart');
  const end=document.querySelector('#v093EventEnd');
  const active=document.querySelector('#v093EventActive');

  if(name)name.value=x.name;
  if(desc)desc.value=x.desc;
  if(start)start.value=v274LocalInput(now);
  if(end)end.value=v274LocalInput(later);
  if(active)active.checked=true;

  document.querySelector('#v093EventName')?.scrollIntoView({behavior:'smooth',block:'center'});
  v063Toast?.(`${x.name} vorbereitet`,'success','Zeitraum prüfen und anschließend „Event speichern“ drücken.');
}

function v274InstallEventPresets(){
  if(!v093IsAdmin)return;
  const root=document.querySelector('#v093AdminContent');
  if(!root)return;

  /* Reuse the existing Dampf helper card instead of stacking another admin card. */
  const card=document.querySelector('#v271AdminDampfCard');
  if(!card)return;

  const title=card.querySelector('h3');
  if(title)title.textContent='🎪 Event-Vorlagen';

  const sub=card.querySelector('.muted');
  if(sub)sub.textContent='Vorlage auswählen, Zeitraum prüfen und anschließend das Event speichern.';

  const state=card.querySelector('#v271AdminDampfState');
  if(state)state.style.display='none';

  const oldInfo=card.querySelector('.v271-admin-dampf-state');
  if(oldInfo)oldInfo.innerHTML='Dampf: <b>300/300</b> · Erfahrung: <b>2× XP</b> · Gold: <b>2× Gold</b> · Mystisch: <b>10 % Chance pro abgeschlossener Quest</b>.';

  const oldBtn=document.querySelector('#v271DampfPreset');
  if(oldBtn)oldBtn.remove();

  let grid=document.querySelector('#v274EventPresets');
  if(!grid){
    grid=document.createElement('div');
    grid.id='v274EventPresets';
    grid.innerHTML=`
      <button class="btn" type="button" data-v274-preset="dampf">💨 Dampf-Event</button>
      <button class="btn" type="button" data-v274-preset="xp">⚡ Erfahrungs-Event</button>
      <button class="btn" type="button" data-v274-preset="gold">💰 Gold-Event</button>
      <button class="btn" type="button" data-v274-preset="mystic">🔷 Mystisch-Event</button>`;
    card.appendChild(grid);
    grid.querySelectorAll('[data-v274-preset]').forEach(btn=>{
      btn.addEventListener('click',()=>v274FillEventPreset(btn.dataset.v274Preset));
    });
  }
}

/* Keep presets installed through the repaired V4.02 admin lifecycle. */
const v274BaseAdminCheck=v093CheckAdmin;
v093CheckAdmin=async function(){
  const r=await v274BaseAdminCheck();
  if(r)v274InstallEventPresets();
  return r;
};
const v274BaseAdminLists=v093AdminLoadLists;
v093AdminLoadLists=async function(){
  const r=await v274BaseAdminLists();
  if(v093IsAdmin)v274InstallEventPresets();
  return r;
};

/* Add concise live bonuses to the world event area without changing DB rows. */
const v274BaseActiveEvents=v085ActiveEvents;
v085ActiveEvents=function(){
  let html=v274BaseActiveEvents();
  const badges=[];
  if(v274GoldEventActive())badges.push('<span class="v274-event-live">💰 2× GOLD</span>');
  if(v274MysticEventActive())badges.push('<span class="v274-event-live">🔷 MYSTISCH AKTIV</span>');
  if(!badges.length)return html;
